SELECT id, station_id, duty_date, main_officer_id, deputy_officer_id,
       note, group_snapshot_json, gmt_create, gmt_modified
FROM ccds_duty_day
WHERE station_id = #{stationId}
  AND duty_date = #{dutyDate}

SELECT id, station_id, duty_date, main_officer_id, deputy_officer_id,
       note, group_snapshot_json, gmt_create, gmt_modified
FROM ccds_duty_day
WHERE station_id = #{stationId}
  AND duty_date BETWEEN #{startDate} AND #{endDate}
ORDER BY duty_date ASC
